import logging
import sys
import time
from threading import Condition, RLock, Thread, Lock

import six

import ta_ue_plugin_android.uepc.adb_proxy as adb
from ta_ue_plugin_android.uepc.cons_usb import UsbCons
from ta_ue_plugin_android.uepc.socket_control import SocketControl
from ta_ue_plugin_android.uepc.ue_manager_exceptions import InfoWaitTimeOutException, UeConnectionTimeoutException, \
    UeManagerException, UnknownCmdIdException
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra


class SendReceiveSocketControlThread(Thread, UsbCons):
    """Send Receive Socket Control Thread"""
    # pylint: disable=too-many-instance-attributes
    HEARTBEAT_TIMEOUT = 10

    def __init__(self, ue_sn):
        """
        Basic initialization.
        :param ue_sn:
        """
        self.cmd_storage = CmdResultsStorage()
        self.sock = SocketControl(ue_sn)
        Thread.__init__(self, name="Android-SendReceiveSocketControlThread-" + str(ue_sn))
        raw_logger = logging.getLogger("ute_ue.uepc")
        # must be called after Thread.__init__
        self.logger = LoggerAdapter4EmptyExtra(raw_logger,
                                               {'area': 'USB', 'ue_id': ue_sn})  # TODO: display ue_id in logs
        # self.setDaemon(True)
        # self.daemon = True
        # Dict(key=id, value = Tuple(body, time))
        self._info_time = {}
        self._info_time_lock = Lock()
        self._running = True
        self.ue_sn = ue_sn
        self._last_heartbeat_time = 0
        self._last_heartbeats_on_time_received = 0
        self._any_heartbeat_received = False
        self.to_raise_tuple = None
        self.has_raise_tuple = False
        self._to_send_queue = []
        self._to_send_on_reconnect_queue = []
        self._send_lock = RLock()
        self._send_condition = Condition()
        self._thread_end_condition = Condition()
        self._info_updated_condition = Condition()

    def clear_reconnect_queue(self):
        """Clears queue of msgs to resend on reconnect to UE."""
        self._to_send_on_reconnect_queue = []

    def await_fresh_heartbeats(self, expect_heartbeats=6, timeout=120, should_raise=True):
        """
        Waits until fresh heartbeats come.
        :param expect_heartbeats:
        :param timeout:
        """
        expect_heartbeats = int(expect_heartbeats)
        start_time = self._now()
        while self._last_heartbeats_on_time_received < expect_heartbeats and self._now() - start_time <= timeout:
            time.sleep(0.05)
            self._check_raise_thread_exception()
        if self._now() - start_time > timeout:
            args = (expect_heartbeats, timeout, self.HEARTBEAT_TIMEOUT)
            msg = "Waiting for heartbeats timeout, expected heartbeats: %d, timeout: %d, HEARTBEAT_TIMEOUT: %d" % args
            if should_raise:
                raise UeConnectionTimeoutException(msg)
            return False
        return True

    def wish_to_send_msg(self, msg_id, body, resend_on_reconnect=False, block_unitl_send=False,
                         block_unitl_send_timeout=None):
        """
        Adds packet to send queue. It will be send to UE.
        :param msg_id:
        :param body:
        :param resend_on_reconnect: bool
        :param block_unitl_send: bool
        :param block_unitl_send_timeout: timeot or None
        :return: sent data with STX & ETX
        """
        with self._send_lock:
            msg = ("%s" * 4) % (self.STX, msg_id, body, self.ETX)
            self._to_send_queue.append(msg)
            if resend_on_reconnect:
                self._to_send_on_reconnect_queue.append(msg)
        if block_unitl_send:
            with self._send_condition:
                self._send_condition.wait(block_unitl_send_timeout)
        return msg

    def _remove_from_send_in_reconnect_queue(self, msg):
        try:
            self._to_send_on_reconnect_queue.remove(msg)
        except ValueError:
            pass

    def _pop_to_send_data(self):
        send_queue = self._to_send_queue
        result = ''
        result += self.HEARTBEAT_MSG
        result += ''.join(send_queue)
        if send_queue:
            self.logger.debug('sending to ue %s data: %s' % (self.sock.ue_sn, result))
        self._to_send_queue = []
        return result

    def _unlock_send_waiters(self):
        with self._info_updated_condition:
            self._info_updated_condition.notifyAll()
        with self._send_condition:
            self._send_condition.notifyAll()

    def wait_until_info_update_and_get_info(self, msg_id, timeout=20, get_info_packet_body='',
                                            msg_validator=lambda msg: True):
        """
        Blocks  your thread until info will be updated, after request sent by this method.
        :param msg_id:
        :param timeout:
        :param get_info_packet_body:
        :param msg_validator used to check if this is the awaited msg
        :return:
        """
        start_time = self._now()
        msg = self.wish_to_send_msg(msg_id, get_info_packet_body, True, True, 10)
        while self.get_info_time(msg_id) < start_time:
            if timeout and self._now() > start_time + timeout:
                break
            self._info_updated_condition_wait(timeout)
        self._remove_from_send_in_reconnect_queue(msg)
        if self.get_info_time(msg_id) >= start_time:
            end_time = self._now() + timeout
            while self._now() < end_time:
                msg = self.get_info(msg_id)
                if msg_validator(msg):
                    return msg
                time.sleep(0.1)
        raise InfoWaitTimeOutException()

    def _info_updated_condition_wait(self, timeout):
        with self._info_updated_condition:
            if timeout:
                self._info_updated_condition.wait(timeout)
            else:
                self._info_updated_condition.wait()

    def get_info(self, msg_id):
        """
        Returns last received info with specified id.
        :param msg_id:
        :return:
        """
        with self._info_time_lock:
            if msg_id not in self._info_time:
                return False
            body, info_time = self._info_time[msg_id]
            if info_time == 0:
                return False
            return body

    def get_info_time(self, msg_id):
        """
        Get time specified info arrived.
        :param msg_id:
        :return: time
        """
        with self._info_time_lock:
            if msg_id not in self._info_time:
                return 0
            _, t = self._info_time[msg_id]
            return t

    def _check_raise_thread_exception(self):
        if self.has_raise_tuple:
            a, b, c = self.to_raise_tuple
            six.reraise(a, b, c)

    def run(self):
        """Connection thread's run method."""
        try:
            while self._running:
                ue_sn = self.sock.ue_sn
                self.logger.debug("running next single_connection_cycle with ue %s" % ue_sn)
                self._single_connection_cycle_until_error_or_disconnect()
                if not self._running:
                    break
                self.handle_cant_connect()
                time.sleep(1)
        except Exception as e:  # pylint: disable=broad-except
            self.logger.debug("Exception in SendReceiveSocketControlThread: {}".format(getattr(e, 'message', str(e))))
            a, b, c = sys.exc_info()
            self.to_raise_tuple = (a, b, c)
            self.has_raise_tuple = True
        with self._thread_end_condition:
            self._thread_end_condition.notifyAll()

    def _single_connection_cycle_until_error_or_disconnect(self):
        self._connect_and_handle_exception()
        if not self.sock.connected():
            return False
        self._last_heartbeat_time = self._now()
        self._any_heartbeat_received = False
        with self._send_lock:
            self._to_send_queue = self._to_send_on_reconnect_queue
        try:
            while self._running and self.sock.connected():
                self._io_step_with_throwing()
                time.sleep(0.09)
                heartbeat_age = self._now() - self._last_heartbeat_time
                if heartbeat_age > self.HEARTBEAT_TIMEOUT:
                    self.logger.warning(
                        "heartbeat timeout in ue %s, with heartbeat_age = %d" % (self.sock.ue_sn, heartbeat_age))
                    self.sock.close()
                    return self._any_heartbeat_received
            self.sock.close()
        except Exception as e:
            self.logger.debug("\n---------------------------------------------\n"
                              "UE CONNECTION DROPPED: {}, {}\n"
                              "---------------------------------------------\n".format(self.ue_sn, e))
            self.logger.error(e, exc_info=True)
            raise
        finally:
            self._last_heartbeats_on_time_received = 0
            return self._any_heartbeat_received  # pylint: disable=lost-exception

    @staticmethod
    def _now():
        return time.time()

    def _connect_and_handle_exception(self):
        try:
            self.sock.connect()
        except UeManagerException as e:
            self.logger.warning("Internal exception while connecting to ue: %s" % self.sock.ue_sn)
            self.logger.exception(e, exc_info=True)
        except Exception as e:  # pylint: disable=broad-except
            self.logger.warning("Non-internal exception while connecting to ue: %s" % self.sock.ue_sn)
            self.logger.exception(e, exc_info=True)

    def _io_step_with_throwing(self):
        self.sock.io_step_with_select_select(lambda: self._pop_to_send_data(),
                                             lambda: self._unlock_send_waiters())  # pylint: disable=unnecessary-lambda
        while self.sock.connected():
            msg_id, body = self.sock.read_packet_from_buffer()
            if not msg_id:
                break
            self._process_new_packet_from_ue(msg_id, body)

    def _process_new_packet_from_ue(self, msg_id, body):
        if msg_id[0] == '\x07':
            # heartbeat response
            self._last_heartbeat_time = self._now()
            self._last_heartbeats_on_time_received += 1
            self._any_heartbeat_received = True
            return
        self.logger.debug("Process packet %s: %s" % (hex(ord(msg_id)), body))
        if msg_id[0] == self.GET_AUTO_CMD_RESULT:
            self.cmd_storage.storage_packet_body(body)
            return
        with self._info_time_lock:
            self._info_time[msg_id] = (body, self._now())
        with self._info_updated_condition:
            self._info_updated_condition.notifyAll()

    def close(self, timeout=None):
        """
        Closes thread (with reconnecting to this UE).
        Blocks this thread until connection thread is stopped.
        :param timeout: float in seconds or None if no timeout
        :return:
        """
        self.logger.debug("Closing socket connection between android app (stopping socket thread)")
        self._running = False
        if not timeout:
            return
        with self._thread_end_condition:
            self._thread_end_condition.wait(timeout)

    def handle_cant_connect(self):
        """Call it each time when you cant connect to UE."""
        self.logger.debug("handle_cant_connect: Make sure UE is available.")
        if not adb.adb_is_ue_available(self.ue_sn,
                                       time_frame=5):  # time_frame needed cause some devices disappear after some time after reboot
            adb.adb_await_for_ue(self.ue_sn, wait_time=120)
            self.logger.debug("handle_cant_connect: Await boot is fully completed")
            adb.adb_await_boot_complete(self.ue_sn, wait_time=120)
        self.logger.debug("handle_cant_connect: Start UE handling app")
        adb.adb_start_mobile_app(self.ue_sn, adb_cmd_runner=adb.get_public_adb_cmd_runner())


class CmdResultsStorage(object):
    """Register for shell commands executed on UE"""

    def __init__(self):
        """Basic initialization."""
        self.callbacks = {}
        self.cmd_ids = []
        self.cmd_id_history = {}

    def storage(self, cmd_id, cmd_body):
        """
        :param cmd_id: 4 char string - something like 'id of Ue Manager Android shell window'
        :param cmd_body:
        :return:
        """
        if cmd_id not in self.cmd_ids:
            self.register_cmd_id(cmd_id)
        if cmd_id in self.callbacks:
            save_it = self.callbacks[cmd_id](cmd_body)
            if not save_it:
                return
        self.cmd_id_history[cmd_id].append(cmd_body)

    def register_cmd_id(self, cmd_id):
        """
        Register command ID.

        :param cmd_id:
        """
        self.cmd_ids.append(cmd_id)
        self.clear_history(cmd_id)

    def clear_history(self, cmd_id):
        """
        Clear history.
        :param cmd_id: 4 char string - something like 'id of Ue Manager Android shell window'
        """
        self.cmd_id_history[cmd_id] = []

    def get_history(self, cmd_id):
        """
        :param cmd_id: 4 char string - something like 'id of Ue Manager Android shell window'
        :return: array of strings
        """
        self._check(cmd_id)
        return self.cmd_id_history[cmd_id]

    def get_last(self, cmd_id):
        """
        :param cmd_id: 4 char string - something like 'id of Ue Manager Android shell window'
        :return: string
        """
        self._check(cmd_id)
        return self.get_history(cmd_id)[-1]

    def storage_packet_body(self, packet_body):
        """
        To Receive data from ubs packet.
        :param packet_body: cmdID + cmdBody
        """
        cmd_id = packet_body[0:4]
        cmd_body = packet_body[4:]
        self.storage(cmd_id, cmd_body)

    def set_cmd_result_callback(self, cmd_id, callback):
        """
        Plug you callback on new cmd results.
        Callback must return bool.
        True means 'also save this cmd result in history'
        False means 'dont save this cmd result in history'
        :param cmd_id: 4 char string - something like 'id of Ue Manager Android shell window'
        :param callback:
        """
        self.callbacks[cmd_id] = callback

    def _check(self, cmd_id):
        if cmd_id not in self.cmd_ids:
            raise UnknownCmdIdException("Unsuppored cmdId = " + str(cmd_id))
